select t.machine_id,t.machine_id machineId,t.machine_code,t.machine_code machineCode,t.upload_date,t.upload_date
uploadDate,t.wlt_id,t.wlt_id wltId,t.staff_name,t.staff_name staffName,t.lon,t.status_cd,t.status_cd
statusCd,t.store_id,t.store_id storeId,t.staff_id,t.staff_id staffId,t.pos_type,t.pos_type posType,t.lat,
t.create_time createTime
from work_license_pos t
where 1 =1

    and t.machine_id= #{machineId}


    and t.machine_code= #{machineCode}


    and t.upload_date= #{uploadDate}


    and t.wlt_id= #{wltId}


    and t.staff_name= #{staffName}


    and t.lon= #{lon}


    and t.status_cd= #{statusCd}


    and t.store_id= #{storeId}


    and t.staff_id= #{staffId}


    and t.pos_type= #{posType}


    and t.lat= #{lat}

order by t.create_time desc

    limit #{page}, #{row}

